// --- Integrated pipeline: MaxAbsReduce -> NormalizeScale ->
//     DynamicScaleReciprocal -> RequantTokenCode, per-element, over one
//     realistic token vector. Proves the four C19-C22 primitives compose to
//     the reference's end-to-end per-token codes, not merely that each
//     agrees with itself in isolation. ---

inline constexpr int32_t kPipelineXs0[] = {INT32_C(100), INT32_C(-200), INT32_C(300), INT32_C(-400), INT32_C(500), INT32_C(0), INT32_C(-50)};  // small_typical
